 * Watch the wall-clock playhead against the stitched manifest's ad windows and fire quartile
 * beacons as each ad plays. `playheadDate()` returns the current playhead as epoch ms (from
 * Shaka's getPlayheadTimeAsDate). Returns a stop() cleanup.
 */
export function startAdBeaconWatcher(opts: {
  sessionId: string;
  manifestUrl: string;
  playheadDate: () => number | null;
  refetchMs?: number;
  tickMs?: number;
}): () => void {
  let windows: AdWindow[] = [];
  const fired = new Set<string>(); // `${adId}:${start}:${beacon}`
  let stopped = false;

  async function refresh() {
    try {
      const res = await fetch(opts.manifestUrl, { cache: "no-store" });
      if (res.ok) windows = parseAdWindows(await res.text());
    } catch {
      /* keep prior windows */
    }
  }

  const tick = () => {
    if (stopped) return;
    const now = opts.playheadDate();
    if (now != null) {
      for (const w of windows) {
        if (now < w.start || now > w.end) continue;
        const progress = (now - w.start) / Math.max(1, w.end - w.start);
        for (const [threshold, beacon] of QUARTILES) {
          if (progress + 1e-6 < threshold) continue;
          const key = `${w.adId}:${w.start}:${beacon}`;
          if (fired.has(key)) continue;
          fired.add(key);
          sendAdBeacon(opts.sessionId, beacon, w.adId);
        }
      }
    }
  };

  void refresh();
  const refetch = setInterval(refresh, opts.refetchMs ?? 10_000);
  const ticker = setInterval(tick, opts.tickMs ?? 1_000);
  return () => {
    stopped = true;
    clearInterval(refetch);
    clearInterval(ticker);
  };
}
// Normalize player telemetry (PRD §26B, §28) into canonical ad event types, and
// derive a deterministic event id so duplicate beacons — e.g. a quartile fired
// again after a manifest refresh (PRD §60 task 6) — collapse via the events
// table's ON CONFLICT (event_id) DO NOTHING.

import { createHash } from "node:crypto";

export type CanonicalAdEvent =
  | "ad_impression"
  | "ad_start"
  | "ad_first_quartile"
  | "ad_midpoint"
  | "ad_third_quartile"
  | "ad_complete"
  | "ad_error";

const ALIASES: Record<string, CanonicalAdEvent> = {
  impression: "ad_impression",
  ad_impression: "ad_impression",
  start: "ad_start",
  ad_start: "ad_start",
  firstquartile: "ad_first_quartile",
  first_quartile: "ad_first_quartile",
  ad_first_quartile: "ad_first_quartile",
  midpoint: "ad_midpoint",
  ad_midpoint: "ad_midpoint",
  thirdquartile: "ad_third_quartile",
  third_quartile: "ad_third_quartile",
  ad_third_quartile: "ad_third_quartile",
  complete: "ad_complete",
  ad_complete: "ad_complete",
  error: "ad_error",
  ad_error: "ad_error",
};

const QUARTILE_TO_EVENT: Record<number, CanonicalAdEvent> = {
  0: "ad_start",
  25: "ad_first_quartile",
  50: "ad_midpoint",
  75: "ad_third_quartile",
  100: "ad_complete",
};

export interface RawEvent {
  event?: string;
  event_type?: string;
  event_id?: string;
  quartile?: number;
  session_id?: string;
  channel_id?: string;
  opportunity_id?: string;
  pod_id?: string;
  ad_id?: string;
  campaign_id?: string;
  creative_id?: string;
  program_id?: string;
  playhead_position?: number;
  device_type?: string;
  country?: string;
  payload?: unknown;
  [k: string]: unknown;
}

export interface NormalizedEvent {
  eventId: string;
  eventType: string;
  sessionId: string | null;
  channelId: string | null;
  opportunityId: string | null;
  podId: string | null;
  adId: string | null;
  campaignId: string | null;
  creativeId: string | null;
  programId: string | null;
  playheadPosition: number | null;
  deviceType: string | null;
  country: string | null;
  payload: unknown;
}

/** Resolve the canonical event type from an explicit type or a quartile marker. */
export function canonicalType(raw: RawEvent): string {
  const explicit = (raw.event_type ?? raw.event ?? "").toString();
  const key = explicit.toLowerCase().replace(/\s+/g, "");

  if ((key === "ad_quartile" || key === "quartile") && typeof raw.quartile === "number") {
    return QUARTILE_TO_EVENT[raw.quartile] ?? explicit;
  }
  return ALIASES[key] ?? explicit;
}

/** Deterministic id for lifecycle events so duplicates dedup; unique otherwise. */
export function deriveEventId(raw: RawEvent, eventType: string): string {
  if (raw.event_id) return raw.event_id;

  const isAdLifecycle = eventType.startsWith("ad_") && eventType !== "ad_error";
  if (isAdLifecycle && raw.session_id) {
    const basis = [raw.session_id, raw.pod_id ?? "", raw.ad_id ?? "", eventType].join("|");
    return `evt_${createHash("sha1").update(basis).digest("hex").slice(0, 24)}`;
  }
  // Non-lifecycle (errors, unknown) — let each occurrence be recorded.
  return `evt_${createHash("sha1").update(`${JSON.stringify(raw)}|${Date.now()}|${Math.random()}`).digest("hex").slice(0, 24)}`;
}

export function normalizeEvent(raw: RawEvent): NormalizedEvent | { error: string } {
  const eventType = canonicalType(raw);
  if (!eventType) return { error: "event_type is required" };

  return {
    eventId: deriveEventId(raw, eventType),
    eventType,
    sessionId: raw.session_id ?? null,
    channelId: raw.channel_id ?? null,
    opportunityId: raw.opportunity_id ?? null,
    podId: raw.pod_id ?? null,
    adId: raw.ad_id ?? null,
    campaignId: raw.campaign_id ?? null,
    creativeId: raw.creative_id ?? null,
    programId: raw.program_id ?? null,
    playheadPosition: raw.playhead_position ?? null,
    deviceType: raw.device_type ?? null,
    country: raw.country ?? null,
    payload: raw.payload ?? raw,
  };
}
